import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";"))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    extra_number = 1
    while len(columns) < width:
        name = "extra_" + str(extra_number)
        extra_number += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
